// <auto-generated />
#nullable enable

using System.Collections.Generic;
using CompilerBase;
using VMLAssembler;

namespace CCompiler
{
    public partial class CodeGenerator
{

        private void FlattenArrayInitializer(ASTNode node, List<object> result)
        {
            if (node is ArrayInitializer arrayInit)
            {
                foreach (var elem in arrayInit.Elements)
                {
                    FlattenArrayInitializer(elem, result);
                }
            }
            else if (node is NumberLiteral numLit)
            {
                result.Add(numLit.Value);
            }
            else if (node is CharLiteral charLit)
            {
                result.Add((int)charLit.Value);
            }
            else if (node is StringLiteral strLit)
            {
                result.Add(strLit.Value);
            }
            else if (node is Identifier idLit)
            {
                // 函数名/变量名 → 存储为标签引用
                result.Add(idLit.Name);
            }
            else
            {
                result.Add(0);
            }
        }

        public override VmlProgram GenerateCode()
        {
            // 清理重复函数: 每个函数名只保留最完整的定义(有body优先)
            var funcGroups = ast.Functions.GroupBy(f => f.Name).Where(g => g.Count() > 1).ToList();
            foreach (var g in funcGroups)
            {
                // 优先保留有非空body的定义
                var best = g.FirstOrDefault(f => f.Body != null && f.Body.Statements.Count > 0)
                        ?? g.FirstOrDefault(f => f.Body != null)
                        ?? g.First();
                var toRemove = g.Where(f => f != best).ToList();
                foreach (var f in toRemove) ast.Functions.Remove(f);
            }
            // 优化：移除未使用的全局变量 (但始终注册类型信息)
            var usedGlobalVariables = FindUsedGlobalVariables();
            var usedVariables       = ast.Variables.Where(v => usedGlobalVariables.Contains(v.Name)).ToList();

            // 确保所有数组变量都被包含（即使在FindUsedGlobalVariables中遗漏）
            // 这很重要：匿名struct/union数组变量在成员访问语法中可能被分析遗漏
            foreach (var v in ast.Variables)
            {
                if (v.IsArray && !usedVariables.Any(uv => uv.Name == v.Name))
                    usedVariables.Add(v);
            }

            // 所有全局变量都需要类型信息
            foreach (var varDecl in ast.Variables)
            {
                variableTypes[varDecl.Name] = StringToExprType(varDecl.Type);
                variableTypeStrings[varDecl.Name] = varDecl.Type;
            }

            // 优化：移除未使用的函数
            var usedFunctions    = FindUsedFunctions();
            var usedFunctionList = ast.Functions.Where(f => usedFunctions.Contains(f.Name)).ToList();

            // 处理全局变量
            foreach (var varDecl in usedVariables)
            {
                // 跟踪变量类型
                variableTypes[varDecl.Name] = StringToExprType(varDecl.Type);
                variableTypeStrings[varDecl.Name] = varDecl.Type;

                // 跟踪struct/union类型（含typedef别名）
                var stType = ResolveStructType(varDecl.Type);
                if (stType != null)
                    variableStructTypes[varDecl.Name] = stType;

                if (varDecl.IsArray && (varDecl.ArraySize.HasValue || varDecl.Initializer is ArrayInitializer))
                {
                    // 数组
                    if (varDecl.Initializer is ArrayInitializer arrayInit)
                    {
                        // 数组初始化 - 扁平化嵌套初始化器
                        List<object> initValues = new List<object>();
                        FlattenArrayInitializer(arrayInit, initValues);
                        // 确保数组大小匹配（ArraySize 为 null 时从初始化器推断）
                        int arraySize = varDecl.ArraySize ?? initValues.Count;
                        object[] arrayData = new object[arraySize];
                        for (int i = 0; i < Math.Min(initValues.Count, arrayData.Length); i++)
                        {
                            arrayData[i] = initValues[i];
                        }
                        dataSection[varDecl.Name] = arrayData;
                    }
                    else
                    {
                        // 未初始化的数组
                        dataSection[varDecl.Name] = new int[varDecl.ArraySize ?? 0];
                    }
                }
                else if (varDecl.Initializer is ArrayInitializer structInit
                    && (varDecl.Type.ToLower().StartsWith("struct ") || varDecl.Type.ToLower().StartsWith("union ")))
                {
                    // Struct/union 初始化器: {10, 20}
                    List<object> initValues = new List<object>();
                    FlattenArrayInitializer(structInit, initValues);
                    int structSize = GetTypeSizeFromString(varDecl.Type);
                    int numWords = (structSize + 3) / 4;
                    object[] structData = new object[numWords];
                    for (int i = 0; i < Math.Min(initValues.Count, structData.Length); i++)
                    {
                        structData[i] = initValues[i];
                    }
                    dataSection[varDecl.Name] = structData;
                }
                else if (varDecl.Initializer is NumberLiteral numLiteral)
                {
                    // 数值初始化
                    dataSection[varDecl.Name] = numLiteral.Value;
                }
                else if (varDecl.Initializer is StringLiteral strLiteral)
                {
                    // 字符串初始化
                    dataSection[varDecl.Name] = strLiteral.Value;
                }
                else
                {
                    // 未初始化
                    dataSection[varDecl.Name] = 0;
                }
            }

            // // 生成VGA显示函数
            // GenerateVGAPrint();

            // 处理函数
            foreach (var function in usedFunctionList)
            {
                GenerateFunction(function);
            }

            return BuildProgram("main");
        }

        private HashSet<string> FindUsedGlobalVariables()
        {
            HashSet<string> usedVariables = new HashSet<string>();

            foreach (var function in ast.Functions)
            {
                FindUsedVariablesInFunction(function, usedVariables);
            }

            return usedVariables;
        }

        private void FindUsedVariablesInFunction(Function function, HashSet<string> usedVariables)
        {
            // 检查函数参数
            foreach (var param in function.Params)
            {
                usedVariables.Add(param.Name);
            }

            // 检查函数体（跳过函数声明）
            if (function.Body != null)
            {
                FindUsedVariablesInBlock(function.Body, usedVariables);
            }
        }

        private void FindUsedVariablesInBlock(Block block, HashSet<string> usedVariables)
        {
            foreach (var statement in block.Statements)
            {
                FindUsedVariablesInStatement(statement, usedVariables);
            }
        }

        private void FindUsedVariablesInStatement(ASTNode statement, HashSet<string> usedVariables)
        {
            if (statement is VariableDecl varDecl)
            {
                // 检查初始化器
                if (varDecl.Initializer != null)
                {
                    FindUsedVariablesInExpression(varDecl.Initializer, usedVariables);
                }
            }
            else if (statement is IfStatement ifStmt)
            {
                FindUsedVariablesInExpression(ifStmt.Condition, usedVariables);
                FindUsedVariablesInBlock(ifStmt.ThenBranch, usedVariables);
                if (ifStmt.ElseBranch != null)
                {
                    FindUsedVariablesInBlock(ifStmt.ElseBranch, usedVariables);
                }
            }
            else if (statement is WhileStatement whileStmt)
            {
                FindUsedVariablesInExpression(whileStmt.Condition, usedVariables);
                FindUsedVariablesInBlock(whileStmt.Body, usedVariables);
            }
            else if (statement is DoWhileStatement doWhileStmt)
            {
                FindUsedVariablesInExpression(doWhileStmt.Condition, usedVariables);
                FindUsedVariablesInBlock(doWhileStmt.Body, usedVariables);
            }
            else if (statement is ForStatement forStmt)
            {
                if (forStmt.Init != null)
                {
                    FindUsedVariablesInExpression(forStmt.Init, usedVariables);
                }
                if (forStmt.Condition != null)
                {
                    FindUsedVariablesInExpression(forStmt.Condition, usedVariables);
                }
                if (forStmt.Update != null)
                {
                    FindUsedVariablesInExpression(forStmt.Update, usedVariables);
                }
                FindUsedVariablesInBlock(forStmt.Body, usedVariables);
            }
            else if (statement is ReturnStatement returnStmt)
            {
                if (returnStmt.Value != null)
                {
                    FindUsedVariablesInExpression(returnStmt.Value, usedVariables);
                }
            }
            else if (statement is ExpressionStatement exprStmt)
            {
                FindUsedVariablesInExpression(exprStmt.Expression, usedVariables);
            }
            else if (statement is SwitchStatement switchStmt)
            {
                FindUsedVariablesInExpression(switchStmt.Expression, usedVariables);
                foreach (var caseStmt in switchStmt.Cases)
                {
                    FindUsedVariablesInExpression(caseStmt.Value, usedVariables);
                    FindUsedVariablesInBlock(caseStmt.Body, usedVariables);
                }
                if (switchStmt.Default != null)
                {
                    FindUsedVariablesInBlock(switchStmt.Default.Body, usedVariables);
                }
            }
            else if (statement is LabeledStatement labeledStmt)
            {
                FindUsedVariablesInStatement(labeledStmt.Statement, usedVariables);
            }
        }

        private void FindUsedVariablesInExpression(ASTNode expression, HashSet<string> usedVariables)
        {
            if (expression == null)
            {
                return;
            }

            if (expression is Identifier ident)
            {
                usedVariables.Add(ident.Name);
            }
            else if (expression is BinaryOp binaryOp)
            {
                FindUsedVariablesInExpression(binaryOp.Left,  usedVariables);
                FindUsedVariablesInExpression(binaryOp.Right, usedVariables);
            }
            else if (expression is UnaryOp unaryOp)
            {
                FindUsedVariablesInExpression(unaryOp.Operand, usedVariables);
            }
            else if (expression is Assignment assignment)
            {
                FindUsedVariablesInExpression(assignment.Target, usedVariables);
                FindUsedVariablesInExpression(assignment.Value,  usedVariables);
            }
            else if (expression is CastExpr castExpr)
            {
                FindUsedVariablesInExpression(castExpr.Expression, usedVariables);
            }
            else if (expression is FunctionCall funcCall)
            {
                foreach (var arg in funcCall.Args)
                {
                    FindUsedVariablesInExpression(arg, usedVariables);
                }
            }
            else if (expression is ArrayAccess arrayAccess)
            {
                FindUsedVariablesInExpression(arrayAccess.Array, usedVariables);
                FindUsedVariablesInExpression(arrayAccess.Index, usedVariables);
            }
            else if (expression is ArrayInitializer arrayInit)
            {
                foreach (var element in arrayInit.Elements)
                {
                    FindUsedVariablesInExpression(element, usedVariables);
                }
            }
            else if (expression is ConditionalOp condOp)
            {
                FindUsedVariablesInExpression(condOp.Condition, usedVariables);
                FindUsedVariablesInExpression(condOp.TrueExpr, usedVariables);
                FindUsedVariablesInExpression(condOp.FalseExpr, usedVariables);
            }
            else if (expression is MemberAccess memberAccess)
            {
                FindUsedVariablesInExpression(memberAccess.Object, usedVariables);
            }
        }

        private HashSet<string> FindUsedFunctions()
        {
            // 可达性分析：从入口点 (main + 中断函数) 出发，BFS 遍历调用图
            HashSet<string> usedFunctions = new HashSet<string>();
            Queue<string> worklist = new Queue<string>();

            // 种子：main + 中断处理函数
            foreach (var func in ast.Functions)
            {
                if (func.Name == "main" || func.IsInterrupt)
                {
                    usedFunctions.Add(func.Name);
                    worklist.Enqueue(func.Name);
                }
            }

            // 如果没有入口点（无 main 且无中断函数），保留所有函数（例如库编译或测试）
            if (worklist.Count == 0)
            {
                foreach (var func in ast.Functions)
                    usedFunctions.Add(func.Name);
                return usedFunctions;
            }

            // BFS 遍历函数体中的调用
            while (worklist.Count > 0)
            {
                string funcName = worklist.Dequeue();
                // 优先查找有函数体的定义（声明可能在定义之前）
                var func = ast.Functions.FirstOrDefault(f => f.Name == funcName && f.Body != null)
                        ?? ast.Functions.FirstOrDefault(f => f.Name == funcName);
                if (func == null || func.Body == null) continue;

                var calls = new HashSet<string>();
                FindUsedFunctionsInBlock(func.Body, calls);

                foreach (var called in calls)
                {
                    if (usedFunctions.Add(called))
                        worklist.Enqueue(called);
                }
            }

            return usedFunctions;
        }

        private void FindUsedFunctionsInFunction(Function function, HashSet<string> usedFunctions)
        {
            if (function.Body != null)
                FindUsedFunctionsInBlock(function.Body, usedFunctions);
        }

        private void FindUsedFunctionsInBlock(Block block, HashSet<string> usedFunctions)
        {
            foreach (var statement in block.Statements)
            {
                FindUsedFunctionsInStatement(statement, usedFunctions);
            }
        }

        private void FindUsedFunctionsInStatement(ASTNode statement, HashSet<string> usedFunctions)
        {
            if (statement is IfStatement ifStmt)
            {
                FindUsedFunctionsInExpression(ifStmt.Condition, usedFunctions);
                FindUsedFunctionsInBlock(ifStmt.ThenBranch, usedFunctions);
                if (ifStmt.ElseBranch != null)
                {
                    FindUsedFunctionsInBlock(ifStmt.ElseBranch, usedFunctions);
                }
            }
            else if (statement is WhileStatement whileStmt)
            {
                FindUsedFunctionsInExpression(whileStmt.Condition, usedFunctions);
                FindUsedFunctionsInBlock(whileStmt.Body, usedFunctions);
            }
            else if (statement is DoWhileStatement doWhileStmt)
            {
                FindUsedFunctionsInExpression(doWhileStmt.Condition, usedFunctions);
                FindUsedFunctionsInBlock(doWhileStmt.Body, usedFunctions);
            }
            else if (statement is ForStatement forStmt)
            {
                if (forStmt.Init != null)
                {
                    FindUsedFunctionsInExpression(forStmt.Init, usedFunctions);
                }
                if (forStmt.Condition != null)
                {
                    FindUsedFunctionsInExpression(forStmt.Condition, usedFunctions);
                }
                if (forStmt.Update != null)
                {
                    FindUsedFunctionsInExpression(forStmt.Update, usedFunctions);
                }
                FindUsedFunctionsInBlock(forStmt.Body, usedFunctions);
            }
            else if (statement is ReturnStatement returnStmt)
            {
                if (returnStmt.Value != null)
                {
                    FindUsedFunctionsInExpression(returnStmt.Value, usedFunctions);
                }
            }
            else if (statement is ExpressionStatement exprStmt)
            {
                FindUsedFunctionsInExpression(exprStmt.Expression, usedFunctions);
            }
            else if (statement is SwitchStatement switchStmt)
            {
                FindUsedFunctionsInExpression(switchStmt.Expression, usedFunctions);
                foreach (var caseStmt in switchStmt.Cases)
                {
                    FindUsedFunctionsInExpression(caseStmt.Value, usedFunctions);
                    FindUsedFunctionsInBlock(caseStmt.Body, usedFunctions);
                }
                if (switchStmt.Default != null)
                {
                    FindUsedFunctionsInBlock(switchStmt.Default.Body, usedFunctions);
                }
            }
            else if (statement is VariableDecl varDecl)
            {
                if (varDecl.Initializer != null)
                {
                    FindUsedFunctionsInExpression(varDecl.Initializer, usedFunctions);
                }
            }
            else if (statement is LabeledStatement labeledStmt)
            {
                FindUsedFunctionsInStatement(labeledStmt.Statement, usedFunctions);
            }
            else if (statement is AsmStatement asmStmt)
            {
                // 内联汇编可能包含 CALL label，提取标签名
                var asmCode = asmStmt.Code;
                if (!string.IsNullOrEmpty(asmCode))
                {
                    int callIdx = asmCode.IndexOf("CALL ");
                    if (callIdx >= 0)
                    {
                        string afterCALL = asmCode.Substring(callIdx + 5).Trim();
                        string label = afterCALL.Split(' ')[0].Split('\n')[0].Split('\r')[0].Trim();
                        if (!string.IsNullOrEmpty(label) && ast.Functions.Exists(f => f.Name == label))
                            usedFunctions.Add(label);
                    }
                }
            }
        }

        private void FindUsedFunctionsInExpression(ASTNode expression, HashSet<string> usedFunctions)
        {
            if (expression is BinaryOp binaryOp)
            {
                FindUsedFunctionsInExpression(binaryOp.Left,  usedFunctions);
                FindUsedFunctionsInExpression(binaryOp.Right, usedFunctions);
            }
            else if (expression is UnaryOp unaryOp)
            {
                FindUsedFunctionsInExpression(unaryOp.Operand, usedFunctions);
            }
            else if (expression is Assignment assignment)
            {
                FindUsedFunctionsInExpression(assignment.Target, usedFunctions);
                FindUsedFunctionsInExpression(assignment.Value,  usedFunctions);
            }
            else if (expression is FunctionCall funcCall)
            {
                usedFunctions.Add(funcCall.Name);
                foreach (var arg in funcCall.Args)
                {
                    FindUsedFunctionsInExpression(arg, usedFunctions);
                }
            }
            else if (expression is ArrayAccess arrayAccess)
            {
                FindUsedFunctionsInExpression(arrayAccess.Array, usedFunctions);
                FindUsedFunctionsInExpression(arrayAccess.Index, usedFunctions);
            }
            else if (expression is ArrayInitializer arrayInit)
            {
                foreach (var element in arrayInit.Elements)
                {
                    FindUsedFunctionsInExpression(element, usedFunctions);
                }
            }
            else if (expression is Identifier ident)
            {
                // 函数名在表达式中退化为函数指针: e.g. fp = myFunc
                if (ast.Functions.Exists(f => f.Name == ident.Name))
                    usedFunctions.Add(ident.Name);
            }
            else if (expression is ConditionalOp condOp)
            {
                FindUsedFunctionsInExpression(condOp.Condition, usedFunctions);
                FindUsedFunctionsInExpression(condOp.TrueExpr, usedFunctions);
                FindUsedFunctionsInExpression(condOp.FalseExpr, usedFunctions);
            }
        }

        private void GenerateFunction(Function function)
        {
            if (function.Body == null) return;
            CurrentFunction = function;

            // 使用函数的原始名称作为标签 (支持 VML_PREFIX 前缀替换)
            string funcLabel = ApplyVmlPrefix(function.Name);
            AddLabel(funcLabel); // 注册标签到 labels 字典, 同时保留 LABEL 指令供 VMLAssembler 使用

            // 添加函数注释
            Emit(OpCode.NOP, new List<Operand>(), "; -------------------------------------------");
            // 生成源函数声明
            var sourceDecl = $"{function.ReturnType} {function.Name}(";
            for (var i = 0; i < function.Params.Count; i++)
            {
                sourceDecl += $"{function.Params[i].Type} {function.Params[i].Name}";
                if (i < function.Params.Count - 1)
                {
                    sourceDecl += ",";
                }
            }
            sourceDecl += ")";
            instructions.Add(new Instruction(OpCode.NOP, [], 0, $"; source   : {sourceDecl}"));
            // 生成函数名注释
            instructions.Add(new Instruction(OpCode.NOP, [], 0, $"; function : {function.Name}"));
            // 生成参数注释
            foreach (var param in function.Params)
            {
                instructions.Add(new Instruction(OpCode.NOP, [], 0, $"; param   : {param.Type} {param.Name}"));
            }
            // 生成返回类型注释
            instructions.Add(new Instruction(OpCode.NOP, [], 0, $"; return   : {function.ReturnType}"));
            instructions.Add(new Instruction(OpCode.NOP, [], 0, "; --------------------------------------------"));
            // 添加函数标签指令
            AddLabel(funcLabel);
            // 函数序言
            GenerateFunctionPrologue(function);

            if (function.Body != null)
            {
                // 处理普通函数体
                GenerateBlock(function.Body);
            }

            // 函数 main 自动生成退出系统调用（使用 R0 中的返回值作为退出码）
            if (function.Name == "main")
            {
                EmitExit();
            }

            // 函数尾声
            GenerateFunctionEpilogue(function);
        }

        /// <summary>
        /// 如果编译时定义了 VML_PREFIX=xxx，则将函数名中 shared_/vml_ 替换为指定前缀
        /// 支持多个空格分隔的前缀 — 将额外前缀作为别名标签添加
        /// </summary>
        private string ApplyVmlPrefix(string funcName)
        {
            var opts = VMLPlugins.CompilerOptionsContext.Current;
            string? allPrefixes = null;
            foreach (var d in opts.Defines)
            {
                if (d.StartsWith("VML_PREFIX="))
                {
                    allPrefixes = d["VML_PREFIX=".Length..];
                    break;
                }
            }
            if (string.IsNullOrEmpty(allPrefixes)) return funcName;

            // 分割多个前缀 (空格分隔)
            var prefixes = allPrefixes.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            if (prefixes.Length == 0) return funcName;

            // 提取基础函数名 (去除 vml_ 前缀)
            string baseName = funcName;
            if (baseName.StartsWith("vml_"))
                baseName = baseName["vml_".Length..];

            // 跳过空的基础名
            if (string.IsNullOrEmpty(baseName)) return funcName;

            // 首个前缀生成主标签
            string primaryLabel = prefixes[0] + baseName;
            // 其余前缀添加为别名标签
            for (int i = 1; i < prefixes.Length; i++)
            {
                string aliasLabel = prefixes[i] + baseName;
                if (!string.IsNullOrEmpty(aliasLabel) && aliasLabel != primaryLabel)
                    AddLabel(aliasLabel);
            }
            return primaryLabel;
        }

        private void RegisterStructParamType(Parameter param)
        {
            if (param.Type.ToLower().StartsWith("struct ") || param.Type.ToLower().StartsWith("union ")
                || ResolveStructType(param.Type) != null)
            {
                variableStructTypes[param.Name] = ResolveStructType(param.Type) ?? param.Type.ToLower();
            }
        }

        private void GenerateFunctionPrologue(Function function)
        {
            // 栈帧布局 (R12 为基址):
            //   arg N-1     ← R12 + 12 + 4*(N-1)
            //   arg 0       ← R12 + 12
            //   return addr ← R12 + 8    (CALL压入)
            //   saved R15   ← R12 + 4    (PUSH R15)
            //   saved R12   ← R12 + 0    (PUSH R12, R12指向这里)
            //   local 0     ← R12 - 4
            //   local 1     ← R12 - 8
            //   ...         ← SP

            // 标准序言: PUSH R15; PUSH R12; MOVE R12, R13
            EmitPrologue();

            // 中断函数：额外保存所有通用寄存器（R0-R11）
            if (function.IsInterrupt)
            {
                for (int i = 0; i < 12; i++)
                    instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new(OperandType.REGISTER, i) }));
            }

            // 计算局部变量空间
            stackFrameSize = 0;
            variables      = new Dictionary<string, int>();
            staticLocals   = new Dictionary<string, string>();
            variableTypes  = new Dictionary<string, ExprType>();
            arrayLocalVars = new HashSet<string>();
            localArrayDimensions = new Dictionary<string, List<int?>>();

            // 使用 VarMemManager 统一管理参数和局部变量分配
            Vars?.ResetLocals();

            // 注册参数到符号表（参数编号 0,1,2...）
            // 栈帧布局 (R12 为基址):
            //   arg N-1     ← R12 + 12 + 4*(N-1)
            //   arg 0       ← R12 + 12
            //   return addr ← R12 + 8    (CALL压入)
            //   saved R15   ← R12 + 4    (PUSH R15)
            //   saved R12   ← R12 + 0    (PUSH R12, R12指向这里)
            //   local 0     ← R12 - 4
            //   local 1     ← R12 - 8
            //   ...         ← SP
            hiddenReturnPtrOffset = -1;

            // For functions returning a struct, an implicit hidden pointer arrives
            // as the first "parameter" (in R0 for CCv2). Store it at R12+12.
            if (IsStructParamType(function.ReturnType))
            {
                var hiddenInfo = Vars?.AllocParamAt("__hidden_ret", 12, 4);
                if (hiddenInfo != null)
                {
                    hiddenReturnPtrOffset = hiddenInfo.Offset;
                    variables["__hidden_ret"] = hiddenInfo.Offset;
                    variableTypes["__hidden_ret"] = ExprType.Int;
                }
            }

            // 计算寄存器参数个数（用于 fastcall 的偏移分配）
            int regParamCount = function.Convention switch
            {
                CallingConvention.Stdcall => 0,
                CallingConvention.Fastcall => 4,    // fastcall: R0-R3
                _ => 4                              // CCv2: 最多4个寄存器参数
            };

            // 分配参数偏移
            // fastcall: 栈参数在低偏移(R12+12起)，寄存器参数在高偏移，避免覆盖
            //           寄存器参数由 caller 装入 R0-R3，不占用栈空间
            // stdcall:  从左到右压栈，第一个参数在最高偏移，最后一个在 R12+12
            if (function.Convention == CallingConvention.Fastcall && function.Params.Count > regParamCount)
            {
                // 先分配栈参数（索引 >= regParamCount），再分配寄存器参数（索引 0..regParamCount-1）
                for (int i = regParamCount; i < function.Params.Count; i++)
                {
                    var param = function.Params[i];
                    int paramSize = GetTypeSizeFromString(param.Type);
                    var paramInfo = Vars?.AllocParam(param.Name, paramSize);
                    int offset = paramInfo?.Offset ?? 12;
                    variables[param.Name] = offset;
                    variableTypes[param.Name] = StringToExprType(param.Type);
                    variableTypeStrings[param.Name] = param.Type;
                    RegisterStructParamType(param);
                }
                for (int i = 0; i < regParamCount; i++)
                {
                    var param = function.Params[i];
                    int paramSize = GetTypeSizeFromString(param.Type);
                    var paramInfo = Vars?.AllocParam(param.Name, paramSize);
                    int offset = paramInfo?.Offset ?? 12;
                    variables[param.Name] = offset;
                    variableTypes[param.Name] = StringToExprType(param.Type);
                    variableTypeStrings[param.Name] = param.Type;
                    RegisterStructParamType(param);
                }
            }
            else if (function.Convention == CallingConvention.Stdcall)
            {
                // stdcall 和 cdecl 栈布局相同 (均为右→左压栈)
                // 第一个参数在 R12+12，后续参数在高偏移
                // 唯一区别: stdcall 被调用者清理栈 (见 Epilogue)
                foreach (var param in function.Params)
                {
                    int paramSize = GetTypeSizeFromString(param.Type);
                    var paramInfo = Vars?.AllocParam(param.Name, paramSize);
                    int offset = paramInfo?.Offset ?? 12;
                    variables[param.Name] = offset;
                    variableTypes[param.Name] = StringToExprType(param.Type);
                    variableTypeStrings[param.Name] = param.Type;
                    RegisterStructParamType(param);
                }
            }
            else
            {
                foreach (var param in function.Params)
                {
                    int paramSize = GetTypeSizeFromString(param.Type);
                    var paramInfo = Vars?.AllocParam(param.Name, paramSize);
                    int offset = paramInfo?.Offset ?? 12;
                    variables[param.Name] = offset;
                    variableTypes[param.Name] = StringToExprType(param.Type);
                    variableTypeStrings[param.Name] = param.Type;
                    RegisterStructParamType(param);
                }
            }

            // 统计局部变量（不包括参数）
            var localIndex = 0;
            CountLocalVariablesEx(function.Body, ref localIndex);

            // 为局部变量分配栈空间（额外 8 字节安全边界，防止 PUSH/POP 覆盖最后一个局部变量）
            int localVarSpace = Vars?.LocalFrameSize ?? (localIndex * 4);
            int stackAlloc = localVarSpace > 0 ? localVarSpace + 8 : 0;
            if (stackAlloc > 0)
            {
                instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new(OperandType.REGISTER, 13), new(OperandType.IMMEDIATE, stackAlloc) }));
            }

            // 根据调用约定保存寄存器参数到栈帧
            // 使得所有参数可以通过 [R12+offset] 统一访问
            // Struct params always arrive on the stack — skip them for register saving
            int regNum = 0;  // actual register number (R0, R1, ...) — skips struct params

            // For struct-return functions: the hidden return pointer arrives in R0
            // and is stored at R12+12. Save it before handling declared params.
            if (hiddenReturnPtrOffset >= 0 && regNum < regParamCount)
            {
                instructions.Add(new Instruction(OpCode.MOVE,
                    new List<Operand> { new(OperandType.MEMORY, $"R12+{hiddenReturnPtrOffset}"), new(OperandType.REGISTER, regNum) }));
                regNum++;
            }

            for (int i = 0; i < function.Params.Count && regNum < regParamCount; i++)
            {
                var param = function.Params[i];
                var pType = StringToExprType(param.Type);
                int paramSize = GetTypeSizeFromString(param.Type);

                // Struct params are passed on the stack — no register to save
                if (pType == ExprType.Struct)
                    continue;

                int saveOffset = (Vars != null && Vars.TryGetVar(param.Name, out var pvi))
                    ? pvi.Offset : variables[param.Name];

                if (pType == ExprType.Float)
                {
                    instructions.Add(new Instruction(OpCode.I2F, new List<Operand> { new(OperandType.REGISTER, regNum), new(OperandType.REGISTER, regNum) }));
                    instructions.Add(new Instruction(OpCode.MOVEF,
                        new List<Operand> { new(OperandType.MEMORY, $"R12+{saveOffset}"), new(OperandType.REGISTER, regNum) }));
                }
                else if (pType == ExprType.Double)
                {
                    instructions.Add(new Instruction(OpCode.I2D, new List<Operand> { new(OperandType.REGISTER, regNum+16), new(OperandType.REGISTER, regNum) }));
                    instructions.Add(new Instruction(OpCode.MOVED,
                        new List<Operand> { new(OperandType.MEMORY, $"R12+{saveOffset}"), new(OperandType.REGISTER, regNum+16) }));
                }
                else if (paramSize <= 4)
                {
                    instructions.Add(new Instruction(OpCode.MOVE,
                        new List<Operand> { new(OperandType.MEMORY, $"R12+{saveOffset}"), new(OperandType.REGISTER, regNum) }));
                }
                else
                {
                    instructions.Add(new Instruction(OpCode.MOVE,
                        new List<Operand> { new(OperandType.MEMORY, $"R12+{saveOffset}"), new(OperandType.REGISTER, regNum) }));
                }
                regNum++;
            }
        }

        private void GenerateFunctionEpilogue(Function function)
        {
            // 添加函数结束标签
            if (functionEndLabels.ContainsKey(function.Name))
            {
                string endLabel = functionEndLabels[function.Name];
                labels[endLabel] = instructions.Count;
            }

            // 标准尾声帧恢复: MOVE R13, R12; POP R12; POP R15
            // (不调用 EmitEpilogue() 因为 RET 指令因中断/调用约定而异)
            instructions.Add(new Instruction(OpCode.MOVE, [new Operand(OperandType.REGISTER, 13), new Operand(OperandType.REGISTER, 12)]));

            // 中断函数：逆序恢复所有通用寄存器（R11-R0）
            if (function.IsInterrupt)
            {
                for (int i = 11; i >= 0; i--)
                    instructions.Add(new Instruction(OpCode.POP, [new(OperandType.REGISTER, i)]));
            }

            instructions.Add(new Instruction(OpCode.POP, [new Operand(OperandType.REGISTER, 12)]));
            instructions.Add(new Instruction(OpCode.POP, [new Operand(OperandType.REGISTER, 15)]));

            // 返回
            if (function.IsInterrupt)
                instructions.Add(new Instruction(OpCode.IRET, new List<Operand>()));
            else if (function.Convention == CallingConvention.Stdcall && function.Params.Count > 0)
            {
                // stdcall: 被调用者清理栈参数
                // 保存返回地址，清理栈参数，恢复返回地址，RET
                // 使用 R1 作为临时寄存器，避免覆盖 R0（返回值）
                int stackArgBytes = 0;
                foreach (var p in function.Params)
                    stackArgBytes += GetTypeSizeFromString(p.Type);
                // [R13] 当前指向返回地址
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                    new(OperandType.REGISTER, 1), new(OperandType.MEMORY, "R13") }));
                // SP += 4 (跳过返回地址本身) + stackArgBytes (跳过参数)
                instructions.Add(new Instruction(OpCode.ADD, new List<Operand> {
                    new(OperandType.REGISTER, 13), new(OperandType.IMMEDIATE, 4 + stackArgBytes) }));
                // 把返回地址压回栈
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new(OperandType.REGISTER, 1) }));
                instructions.Add(new Instruction(OpCode.RET, new List<Operand>()));
            }
            else
                instructions.Add(new Instruction(OpCode.RET, new List<Operand>()));
        }

        private void CountLocalVariablesEx(ASTNode node, ref int localIndex)
        {
            if (node == null) return;
            if (node is Block block)
            {
                foreach (var stmt in block.Statements)
                    CountLocalVariablesEx(stmt, ref localIndex);
            }
            else if (node is IfStatement ifS)
            {
                CountLocalVariablesEx(ifS.ThenBranch, ref localIndex);
                if (ifS.ElseBranch != null)
                    CountLocalVariablesEx(ifS.ElseBranch, ref localIndex);
            }
            else if (node is WhileStatement whStmt)
            {
                CountLocalVariablesEx(whStmt.Body, ref localIndex);
            }
            else if (node is ForStatement foStmt)
            {
                if (foStmt.Init != null) CountLocalVariablesEx(foStmt.Init, ref localIndex);
                CountLocalVariablesEx(foStmt.Body, ref localIndex);
            }
            else if (node is DoWhileStatement dwStmt)
            {
                CountLocalVariablesEx(dwStmt.Body, ref localIndex);
            }
            else if (node is SwitchStatement swStmt)
            {
                foreach (var c in swStmt.Cases)
                    CountLocalVariablesEx(c.Body, ref localIndex);
                if (swStmt.Default?.Body != null)
                    CountLocalVariablesEx(swStmt.Default.Body, ref localIndex);
            }
            else if (node is LabeledStatement labeled)
            {
                CountLocalVariablesEx(labeled.Statement, ref localIndex);
            }
            else if (node is ReturnStatement) { /* no child blocks */ }
            else if (node is ExpressionStatement) { /* no child blocks */ }
            else if (node is BreakStatement || node is ContinueStatement) { /* no child blocks */ }
            else if (node is GotoStatement) { /* no child blocks */ }
            else if (node is VariableDecl varDecl)
            {
                if (!variables.ContainsKey(varDecl.Name) && !staticLocals.ContainsKey(varDecl.Name))
                {
                    if (varDecl.IsStatic)
                    {
                        // static局部变量: 存储在data section, 不使用栈空间
                        string staticLabel = $"{CurrentFunction.Name}__{varDecl.Name}";
                        staticLocals[varDecl.Name] = staticLabel;
                        dataSection[staticLabel] = 0; // 默认初始值
                        variableTypes[varDecl.Name] = StringToExprType(varDecl.Type);
                        variableTypeStrings[varDecl.Name] = varDecl.Type;
                        var stType3 = ResolveStructType(varDecl.Type);
                        if (stType3 != null)
                            variableStructTypes[varDecl.Name] = stType3;
                        return; // 不计数到localIndex, 不分配栈空间
                    }
                    // 局部变量偏移: 使用 VarMemManager 按类型实际大小分配
                    int allocSize;
                    int elementSize = 4;
                    // VLA: 仅分配指针大小 (4字节)，实际数据运行时动态分配
                    if (varDecl.IsVLA)
                    {
                        allocSize = 4;  // 指针大小
                        elementSize = GetTypeSizeFromString(varDecl.Type);
                        vlaVariables.Add(varDecl.Name);
                        arrayLocalVars.Add(varDecl.Name);
                        localArrayDimensions[varDecl.Name] = new List<int?>();  // empty marker = VLA
                    }
                    // 检测 typedef 数组类型 (varDecl.IsArray 为 false 但类型含 [N])
                    // 需要先解析 typedef 链，因为 varDecl.Type 可能是未解析的别名
                    string resolvedVarType = ResolveTypeName(varDecl.Type);
                    var typeDims = ExtractArrayDimensions(resolvedVarType);
                    bool isArrayByType = typeDims != null && typeDims.Count > 0;
                    if (!varDecl.IsVLA && varDecl.IsArray && (varDecl.ArraySize.HasValue || varDecl.Initializer is ArrayInitializer))
                    {
                        int typeSize = GetTypeSizeFromString(varDecl.Type);
                        elementSize = typeSize;
                        if (varDecl.ArraySize.HasValue)
                            allocSize = varDecl.ArraySize.Value * typeSize;
                        else
                            allocSize = ((ArrayInitializer)varDecl.Initializer).Elements.Count * typeSize;
                        arrayLocalVars.Add(varDecl.Name);
                        if (varDecl.Dimensions != null && varDecl.Dimensions.Count > 0)
                            localArrayDimensions[varDecl.Name] = new List<int?>(varDecl.Dimensions);
                    }
                    else if (isArrayByType)
                    {
                        // typedef 数组类型如 state_t test; (state_t = uint8_t[4][4])
                        string baseType = StripArrayDimensions(resolvedVarType);
                        elementSize = GetTypeSizeFromString(baseType);
                        allocSize = GetTypeSizeFromString(varDecl.Type);
                        arrayLocalVars.Add(varDecl.Name);
                        localArrayDimensions[varDecl.Name] = typeDims;
                    }
                    else
                    {
                        allocSize = GetTypeSizeFromString(varDecl.Type);
                        elementSize = allocSize;
                    }
                    var varInfo = Vars?.AllocLocal(varDecl.Name, allocSize);
                    // 数组元素 0 位于分配区域底部（最低地址），指针算术通过 ADD 向上访问
                    int adjustedOffset = varInfo?.Offset ?? -(4 + 4 * localIndex);
                    if (varInfo != null && (isArrayByType || (varDecl.IsArray && (varDecl.ArraySize.HasValue || varDecl.Initializer is ArrayInitializer))))
                        adjustedOffset = varInfo.Offset;
                    else if (varInfo != null)
                        adjustedOffset = varInfo.Offset + allocSize - elementSize;
                    variables[varDecl.Name] = adjustedOffset;
                    int unitsNeeded = (allocSize + 3) / 4;
                    localIndex += unitsNeeded;
                    variableTypes[varDecl.Name] = StringToExprType(varDecl.Type);
                    variableTypeStrings[varDecl.Name] = varDecl.Type;
                    var stType4 = ResolveStructType(varDecl.Type);
                    if (stType4 != null)
                    {
                        variableStructTypes[varDecl.Name] = stType4;
                    }
                }
            }
            else if (node is IfStatement ifStmt)
            {
                CountLocalVariablesEx(ifStmt.Condition,  ref localIndex);
                CountLocalVariablesEx(ifStmt.ThenBranch, ref localIndex);
                if (ifStmt.ElseBranch != null)
                {
                    CountLocalVariablesEx(ifStmt.ElseBranch, ref localIndex);
                }
            }
            else if (node is WhileStatement whileStmt)
            {
                CountLocalVariablesEx(whileStmt.Condition, ref localIndex);
                CountLocalVariablesEx(whileStmt.Body,      ref localIndex);
            }
            else if (node is DoWhileStatement doWhileStmt)
            {
                CountLocalVariablesEx(doWhileStmt.Condition, ref localIndex);
                CountLocalVariablesEx(doWhileStmt.Body,      ref localIndex);
            }
            else if (node is ForStatement forStmt)
            {
                if (forStmt.Init != null)
                {
                    CountLocalVariablesEx(forStmt.Init, ref localIndex);
                }
                if (forStmt.Condition != null)
                {
                    CountLocalVariablesEx(forStmt.Condition, ref localIndex);
                }
                if (forStmt.Update != null)
                {
                    CountLocalVariablesEx(forStmt.Update, ref localIndex);
                }
                CountLocalVariablesEx(forStmt.Body, ref localIndex);
            }
            else if (node is SwitchStatement switchStmt)
            {
                CountLocalVariablesEx(switchStmt.Expression, ref localIndex);
                foreach (var caseStmt in switchStmt.Cases)
                {
                    CountLocalVariablesEx(caseStmt.Value, ref localIndex);
                    CountLocalVariablesEx(caseStmt.Body, ref localIndex);
                }
                if (switchStmt.Default != null)
                    CountLocalVariablesEx(switchStmt.Default.Body, ref localIndex);
            }
            else if (node is LabeledStatement labeledStmt)
            {
                CountLocalVariablesEx(labeledStmt.Statement, ref localIndex);
            }
        }

        private void GenerateBlock(Block block)
        {
            foreach (var stmt in block.Statements)
            {
                GenerateStatement(stmt);
            }
        }

    }
}  // namespace
